def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    # legend: multicolour object with the most distinct colours
    objs = objects(g, bg=bg, multicolour=True)
    leg = max(objs, key=lambda o: len(set(g[y, x] for y, x in o["cells"])))
    y0, x0, y1, x1 = leg["box"]
    L = g[y0:y1 + 1, x0:x1 + 1]
    mapping = {}
    top, bottom, left, right = y0, H - 1 - y1, x0, W - 1 - x1
    horizontal = (L.shape[0] == 2 and (L.shape[1] != 2 or min(top, bottom) < min(left, right)))
    if horizontal:
        key = 0 if top < bottom else 1
        for c in range(L.shape[1]):
            mapping[int(L[key, c])] = int(L[1 - key, c])
    else:
        key = 0 if left < right else 1
        for r in range(L.shape[0]):
            mapping[int(L[r, key])] = int(L[r, 1 - key])
    emit(out, f"Legend read as key->fill pairs (key side nearest the grid edge): {mapping}")
    # enclosed background regions bordered by a single colour
    for comp in components(g == bg):
        if any(y in (0, H - 1) or x in (0, W - 1) for y, x in comp):
            continue
        cs = set(comp)
        nb = set()
        for y, x in comp:
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if (ny, nx) not in cs and 0 <= ny < H and 0 <= nx < W:
                    nb.add(int(g[ny, nx]))
        if len(nb) == 1:
            c = nb.pop()
            if c in mapping:
                for y, x in comp:
                    out[y, x] = mapping[c]
                emit(out, f"Filled hole of the colour-{c} shape with {mapping[c]}")
    emit(out, "Final grid")
    return out
